        environment=new MockEnvironment();var defaults=new java.util.Properties();try(var in=ControlServersTest.class.getResourceAsStream("/application-integration.properties")){defaults.load(in);}for(var entry:defaults.entrySet())environment.setProperty(entry.getKey().toString(),entry.getValue().toString());environment.withProperty("sms.active","aliyun").withProperty("sms.aliyun.access-key-id","synthetic").withProperty("sms.aliyun.access-key-secret","synthetic").withProperty("sms.aliyun.sign-name","synthetic");
