        id=UUID.randomUUID();byte[] type="ssh-ed25519".getBytes();byte[] wire=java.nio.ByteBuffer.allocate(4+type.length+4+32).putInt(type.length).put(type).putInt(32).put(new byte[32]).array();hostKey="ssh-ed25519 "+Base64.getEncoder().encodeToString(wire);
        Path jar=temp.resolve("candidate.jar");Files.writeString(jar,"synthetic inert artifact");var r=new ControlProperties.Release();r.setArtifact(jar);r.setSha256(DeploymentExecutor.artifactSha(jar));r.setAcceptanceEvidenceId("synthetic-reviewed-test");r.setRollbackCompatible(true);r.setCompatibleFromSha256(List.of(r.getSha256()));settings.getReleases().put("candidate",r);
