    ControlServerController.ServerInput input(UUID request,Long revision,String credential){return new ControlServerController.ServerInput(request,revision,"Fixture", "127.0.0.1",22,"root","CONTROL_HOST","PASSWORD",credential,hostKey,ControlSsh.key(hostKey).get("fingerprint"));}
    Map<String,Object> add(){return servers.save("17",id,input(id,null,"synthetic-ssh-secret"),true);}
    @Test void sudoChoiceIsRevisionedPreservedAndIncludedInIdempotencyProof(){
        var base=input(id,null,"synthetic-ssh-secret");var sudo=new ControlServerController.ServerInput(base.requestId(),null,base.name(),base.host(),base.port(),"ubuntu",base.location(),base.authentication(),base.credential(),base.hostKey(),base.confirmedFingerprint(),"SUDO");
        var added=servers.save("17",id,sudo,true);assertEquals("SUDO",added.get("privilege"));
        var direct=new ControlServerController.ServerInput(base.requestId(),null,base.name(),base.host(),base.port(),"ubuntu",base.location(),base.authentication(),base.credential(),base.hostKey(),base.confirmedFingerprint(),"NONE");
        assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(ControlFailure.class,()->servers.save("17",id,direct,true)).code);
        var edit=new ControlServerController.ServerInput(UUID.randomUUID(),1L,base.name(),base.host(),base.port(),"ubuntu",base.location(),base.authentication(),"",base.hostKey(),base.confirmedFingerprint());
        assertEquals("SUDO",servers.save("17",id,edit,false).get("privilege"));
        assertEquals("SUDO",store.server(id).get("privilege"));
        var downgrade=new ControlServerController.ServerInput(UUID.randomUUID(),2L,base.name(),base.host(),base.port(),"ubuntu",base.location(),base.authentication(),"",base.hostKey(),base.confirmedFingerprint(),"NONE");
        assertEquals("NONE",servers.save("17",id,downgrade,false).get("privilege"));assertEquals(3L,ControlServers.revision(store.server(id)));
    }
    @Test void missingPrivilegeNeverEnablesSudoAndUnknownPrivilegeIsRejected(){
        assertEquals("NONE",add().get("privilege"));var base=input(UUID.randomUUID(),1L,"");
        var invalid=new ControlServerController.ServerInput(base.requestId(),1L,base.name(),base.host(),base.port(),base.username(),base.location(),base.authentication(),"",base.hostKey(),base.confirmedFingerprint(),"ROOT");
        assertEquals("INVALID_SSH_PRIVILEGE",assertThrows(ControlFailure.class,()->servers.save("17",id,invalid,false)).code);assertEquals(1L,ControlServers.revision(store.server(id)));
    }
    @Test void omittedPrivilegeRetainsThePreUpgradeIdempotencyProof()throws Exception{
        var input=input(id,null,"synthetic-ssh-secret");add();
        var old=json.readValue(json.writeValueAsString(input),LinkedHashMap.class);old.remove("privilege");old.remove("credentialId");
        var request=(Map<?,?>)((Map<?,?>)store.read().get("requests")).get(id.toString());
        assertEquals(store.fingerprint(json.writeValueAsString(old)),request.get("hash"));
        assertEquals(id.toString(),servers.save("17",id,input,true).get("id"));
    }
