    @Test void installIsPersistedOnceSharesHandoffLockAndReconcilesWithoutResending()throws Exception{
        add();var p=createPlan();UUID job=UUID.fromString(p.get("id").toString());var reached=new CountDownLatch(1);var release=new CountDownLatch(1);
        when(ssh.call(anyMap(),anyString(),eq(List.of("install")),any(),anyInt())).thenAnswer(inv->{reached.countDown();release.await(5,TimeUnit.SECONDS);throw new java.io.IOException("synthetic lost acknowledgement");});
        assertEquals("QUEUED",installer.execute("17",job).get("state"));assertTrue(reached.await(3,TimeUnit.SECONDS));assertEquals("DEPLOYMENT_RUNNING",deployment.whenIdle(()->fail("Must not hand off during install")));assertEquals("RUNNING",installer.execute("17",job).get("state"));release.countDown();for(int n=0;n<100&&!installer.job(job).get("state").equals("OUTCOME_UNKNOWN");n++)Thread.sleep(20);assertEquals("OUTCOME_UNKNOWN",installer.job(job).get("state"));installer.close();assertEquals("DEPLOYMENT_RECONCILIATION_REQUIRED",deployment.whenIdle(()->fail("Unknown install must fence deployments")));
        var saved=store.readJson(temp.resolve("server-plan-"+job+".json"));when(ssh.call(anyMap(),anyString(),eq(List.of("status")),any(),anyInt())).thenReturn(Map.of("protocol","eatwhat-install-v1","serverId",id.toString(),"jobId",job.toString(),"root","/opt/eatwhat-sites/"+id,"siteId",saved.get("_siteId"),"instanceId",saved.get("_instanceId"),"artifactSha256",p.get("artifactSha256"),"httpPort",18090,"restoreEvidenceId","fresh-install-restore-"+job,"state","SUCCEEDED"));
        assertEquals("SUCCEEDED",installer.reconcile("17",job).get("state"));assertEquals("SUCCEEDED",((Map<?,?>)store.server(id).get("installation")).get("state"));assertNull(deployment.whenIdle(()->{}));verify(ssh,times(1)).call(anyMap(),anyString(),eq(List.of("install")),any(),anyInt());assertFalse(store.readJson(temp.resolve("server-plan-"+job+".json")).containsKey("_payload"));
    }
