        add();var p=createPlan();UUID job=UUID.fromString(p.get("id").toString());when(ssh.call(anyMap(),anyString(),eq(List.of("install")),any(),anyInt())).thenThrow(new java.io.IOException());installer.execute("17",job);for(int n=0;n<100&&!installer.job(job).get("state").equals("OUTCOME_UNKNOWN");n++)Thread.sleep(20);installer.close();
