    @Test void externalInstallationUsesItsOwnRoleSlotAndNoCopiedAdministrator()throws Exception{
        add();createPlan();UUID cluster=UUID.randomUUID();environment.setProperty("app.site.cluster-id",cluster.toString());
        for(int slot:List.of(1,2)){
            var plan=installer.plan("17",id,new ControlServerController.InstallInput(1,"candidate",18090,"https://business.example.invalid/api",false,"EXTERNAL",slot),"INSTALL");
            assertEquals("EXTERNAL",plan.get("mode"));assertEquals(slot,plan.get("allocationSlot"));assertEquals("AUTHORITY_ACCOUNTS_AFTER_JOIN",plan.get("administratorAction"));assertTrue(((List<?>)plan.get("blockers")).contains("INSTALLATION_CLUSTER_CONFIGURATION_REQUIRED"));
            var saved=store.readJson(temp.resolve("server-plan-"+plan.get("id")+".json"));var payload=json.readValue(store.decrypt(saved.get("_payload").toString()),Map.class);assertFalse(payload.containsKey("administrator"));assertFalse(payload.toString().contains("passwordHash"));
            var properties=new Properties();properties.load(new java.io.StringReader(payload.get("properties").toString()));assertEquals("EXTERNAL",properties.getProperty("app.site.mode"));assertEquals(cluster.toString(),properties.getProperty("app.site.cluster-id"));assertEquals(Integer.toString(slot),properties.getProperty("app.site.allocation-slot"));assertEquals("true",properties.getProperty("app.control.enrollment-required"));assertEquals("false",properties.getProperty("app.cluster.enabled"));assertEquals("false",properties.getProperty("app.account.enabled"));
        }
    }
