        assertEquals("CLUSTER_ROLE_SLOT_MISMATCH",assertThrows(ControlFailure.class,()->installer.plan("17",id,new ControlServerController.InstallInput(1,"candidate",18090,"https://business.example.invalid",false,"EXTERNAL",0),"INSTALL")).code);
        assertEquals("SITE_ALLOCATION_REQUIRED",assertThrows(ControlFailure.class,()->installer.plan("17",id,new ControlServerController.InstallInput(1,"candidate",18090,"https://business.example.invalid",false,"EXTERNAL",null),"INSTALL")).code);verifyNoInteractions(ssh);
        createPlanForExplicitCampus();
