    @Test void versionUpdateUsesPrepareThenApplyAndPersistsItsVerifiedVersion()throws Exception{
        add();String old=settings.getReleases().get("candidate").getSha256();String site="server-"+id.toString().replace("-","").substring(0,12);String instance=UUID.randomUUID().toString();store.mutate(data->{var s=(Map<String,Object>)((Map<String,Object>)data.get("servers")).get(id.toString());s.put("installation",new LinkedHashMap<>(Map.of("state","SUCCEEDED","siteId",site,"instanceId",instance,"httpPort",18090,"root","/opt/eatwhat-sites/"+id,"restoreEvidenceId","synthetic-real-fixture-review","currentSha256",old,"appBaseUrl","https://business.example.invalid","clusterMembership","ACTIVE")));return null;});
        var joined=installer.plan("17",id,new ControlServerController.InstallInput(1,"candidate",18090,"https://business.example.invalid",false),"UPDATE");assertEquals("BLOCKED",joined.get("state"));assertTrue(((List<?>)joined.get("blockers")).contains("JOINED_SERVER_CLUSTER_DEPLOYMENT_REQUIRED"));assertEquals("SERVER_PLAN_BLOCKED",assertThrows(ControlFailure.class,()->installer.execute("17",UUID.fromString(joined.get("id").toString()))).code);verifyNoInteractions(ssh);store.mutate(data->{((Map<String,Object>)((Map<String,Object>)((Map<String,Object>)data.get("servers")).get(id.toString())).get("installation")).put("clusterMembership","NOT_JOINED");return null;});
        assertEquals("INSTALLED_SERVER_URL_IMMUTABLE",assertThrows(ControlFailure.class,()->installer.plan("17",id,new ControlServerController.InstallInput(1,"candidate",18090,"https://business.example.invalid/api",false),"UPDATE")).code);verifyNoInteractions(ssh);
        var p=installer.plan("17",id,new ControlServerController.InstallInput(1,"candidate",18090,"https://business.example.invalid",false),"UPDATE");assertEquals("READY",p.get("state"));UUID job=UUID.fromString(p.get("id").toString());var actions=new java.util.concurrent.CopyOnWriteArrayList<String>();when(ssh.call(anyMap(),anyString(),anyList(),any(),anyInt())).thenAnswer(inv->{List<String> args=inv.getArgument(2);String action=args.get(1);actions.add(action);return Map.of("id",job.toString(),"siteId",site,"instanceId",instance,"artifactSha256",old,"fromSha256",old,"state",action.equals("prepare")?"PREPARED":"SUCCEEDED");});installer.execute("17",job);for(int n=0;n<100&&!installer.job(job).get("state").equals("SUCCEEDED");n++)Thread.sleep(20);assertEquals("SUCCEEDED",installer.job(job).get("state"));assertEquals(List.of("prepare","apply"),actions);assertEquals(old,((Map<?,?>)store.server(id).get("installation")).get("currentSha256"));
    }

    @SuppressWarnings("unchecked") Map<String,Object> failedInstallFixture()throws Exception{
        add();UUID source=UUID.randomUUID();var result=new LinkedHashMap<String,Object>();result.put("protocol","eatwhat-install-v1");result.put("serverId",id.toString());result.put("jobId",source.toString());result.put("siteId","server-"+id.toString().replace("-","").substring(0,12));result.put("instanceId",UUID.randomUUID().toString());result.put("artifactSha256",settings.getReleases().get("candidate").getSha256());result.put("root","/opt/eatwhat-sites/"+id);result.put("state","FAILED");result.put("stage","DATABASE_REDIS");result.put("code","FIRST_INSTALL_FAILED_PRESERVED");
        store.saveJson(store.directory().resolve("server-job-"+source+".json"),Map.of("id",source.toString(),"kind","INSTALL","serverId",id.toString(),"state","FAILED","result",result));store.mutate(data->{((Map<String,Object>)((Map<String,Object>)data.get("servers")).get(id.toString())).put("installation",Map.of("state","FAILED","jobId",source.toString()));return null;});
        when(ssh.call(anyMap(),anyString(),eq(List.of("inspect")),any(),anyInt())).thenAnswer(inv->{var stream=new java.io.ByteArrayOutputStream();((ControlSsh.Upload)inv.getArgument(3)).write(stream);var payload=json.readValue(stream.toByteArray(),Map.class);var checked=new LinkedHashMap<>(result);checked.put("protocol","eatwhat-install-recovery-v1");checked.put("sourceJobId",source.toString());checked.put("originalInstallJobId",source.toString());checked.put("eligible",true);checked.put("freezeHash","f".repeat(64));checked.put("httpPort",18090);checked.put("appBaseUrl","https://business.example.invalid/api");checked.put("restoreEvidenceId","fresh-install-restore-"+source);assertEquals(source.toString(),payload.get("sourceJobId"));assertTrue(inv.getArgument(1,String.class).contains("Retained-install recovery agent"));return checked;});return result;
    }
    Map<String,Object> recoveryPlan(Map<String,Object> source){return installer.recoveryPlan("17",id,new ControlServerController.RecoveryInput(1,UUID.fromString(source.get("jobId").toString())));}
    void awaitJob(UUID job,String state)throws Exception{for(int n=0;n<200&&!installer.job(job).get("state").equals(state);n++)Thread.sleep(10);assertEquals(state,installer.job(job).get("state"));}
    Map<String,Object> recoveryReply(Map<String,Object> plan,String state){var reply=new LinkedHashMap<String,Object>();for(String key:List.of("serverId","sourceJobId","siteId","instanceId","artifactSha256","root","originalInstallJobId","httpPort"))reply.put(key,plan.get(key));reply.put("protocol","eatwhat-install-recovery-v1");reply.put("jobId",plan.get("id"));reply.put("state",state);reply.put("restoreEvidenceId","fresh-install-restore-"+plan.get("originalInstallJobId"));return reply;}
    @Test void recoveryUsesFrozenExistingArtifactAndSharesTheDurableDeploymentFence()throws Exception{
        var source=failedInstallFixture();var p=recoveryPlan(source);assertEquals("READY",p.get("state"));String text=json.writeValueAsString(p);assertFalse(text.contains("passwordHash"));assertFalse(text.contains("synthetic-ssh-secret"));UUID task=UUID.fromString(p.get("id").toString());var reached=new CountDownLatch(1);var release=new CountDownLatch(1);
        // A later mutable release edit cannot replace the failed installation's JAR.
        Files.writeString(settings.getReleases().get("candidate").getArtifact(),"new unrelated candidate");
        when(ssh.call(anyMap(),anyString(),eq(List.of("recover")),any(),anyInt())).thenAnswer(inv->{var bytes=new java.io.ByteArrayOutputStream();((ControlSsh.Upload)inv.getArgument(3)).write(bytes);var payload=json.readValue(bytes.toByteArray(),Map.class);assertEquals(source.get("artifactSha256"),payload.get("artifactSha256"));assertEquals("f".repeat(64),payload.get("freezeHash"));reached.countDown();release.await(5,TimeUnit.SECONDS);return recoveryReply(p,"SUCCEEDED");});
        installer.execute("17",task);assertTrue(reached.await(3,TimeUnit.SECONDS));assertEquals("DEPLOYMENT_RUNNING",deployment.whenIdle(()->fail("Recovery must fence handoff")));assertFalse(Files.exists(temp.resolve("server-artifact-"+task+".jar")));assertEquals("RUNNING",installer.execute("17",task).get("state"));release.countDown();awaitJob(task,"SUCCEEDED");assertEquals("SUCCEEDED",((Map<?,?>)store.server(id).get("installation")).get("state"));assertEquals("FAILED",installer.job(UUID.fromString(source.get("jobId").toString())).get("state"));verify(ssh,times(1)).call(anyMap(),anyString(),eq(List.of("recover")),any(),anyInt());assertFalse(store.readJson(temp.resolve("server-plan-"+task+".json")).containsKey("_payload"));
    }
    @Test void recoveryRejectsChangedAdministratorBeforeAcceptance()throws Exception{
        var p=recoveryPlan(failedInstallFixture());when(jdbc.queryForList(anyString(),eq(17L))).thenReturn(List.of(Map.of("nick_name","changed-admin","password_hash",new BCryptPasswordEncoder(4).encode("changed"))));assertEquals("SERVER_PLAN_CHANGED",assertThrows(ControlFailure.class,()->installer.execute("17",UUID.fromString(p.get("id").toString()))).code);verify(ssh,never()).call(anyMap(),anyString(),eq(List.of("recover")),any(),anyInt());
    }
